    html: "<style>\n#st-mochi-celebration .stage {\n      position: relative;\n      width: min(80vmin, 640px);\n      height: min(80vmin, 640px);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n#st-mochi-celebration svg {\n      width: 100%;\n      height: 100%;\n      display: block;\n      overflow: visible;\n    }\n#st-mochi-celebration #body { transform-origin: 627px 985px; animation: celebBody--mochi-celebration 2.8s cubic-bezier(0.35, 0.0, 0.25, 1) infinite;; }\n@keyframes celebBody--mochi-celebration { 0%, 100% { transform: scale(1, 1) translateY(0px) rotate(0deg); } 14% { transform: scale(1.05, 0.94) translateY(7px); } 25% { transform: scale(0.93, 1.08) translateY(-22px); } 36% { transform: scale(1.02, 0.98) translateY(-16px) rotate(4deg) translateX(4px); } 48% { transform: scale(1.02, 0.98) translateY(-16px) rotate(-4deg) translateX(-4px); } 60% { transform: scale(1.01, 0.99) translateY(-14px) rotate(2deg); } 72% { transform: scale(1.04, 0.96) translateY(4px) rotate(0deg); } 86% { transform: scale(0.99, 1.01) translateY(-2px); } }\n#st-mochi-celebration #sprout { transform-origin: 810px 375px; animation: celebSprout--mochi-celebration 2.8s ease-in-out infinite;; }\n@keyframes celebSprout--mochi-celebration { 0%, 100% { transform: rotate(0deg); } 25% { transform: rotate(8deg) scale(1.15); } 38% { transform: rotate(-7deg) scale(1.12); } 50% { transform: rotate(6deg); } 62% { transform: rotate(-4deg); } 75% { transform: rotate(0deg); } }\n#st-mochi-celebration #visor { transform-origin: 627px 615px; animation: celebVisor--mochi-celebration 2.8s cubic-bezier(0.35, 0.0, 0.25, 1) infinite;; }\n@keyframes celebVisor--mochi-celebration { 0%, 100% { transform: translateY(0px) rotate(0deg); } 25% { transform: translateY(-18px); } 38% { transform: translateY(-14px) rotate(3deg); } 48% { transform: translateY(-14px) rotate(-3deg); } 72% { transform: translateY(3px) rotate(0deg); } }\n#st-mochi-celebration .eye { transform-box: fill-box; transform-origin: center 65%; animation: celebEyes--mochi-celebration 2.8s infinite;; }\n@keyframes celebEyes--mochi-celebration { 0%, 100% { transform: scale(1, 1); } 25%, 62% { transform: scale(1.15, 1.25); } 75% { transform: scale(1, 1); } }\n#st-mochi-celebration #blush { transform-origin: 627px 700px; animation: celebBlush--mochi-celebration 2.8s ease-in-out infinite;; }\n@keyframes celebBlush--mochi-celebration { 0%, 100% { opacity: 0.9; transform: scale(1); } 25%, 62% { opacity: 1; transform: scale(1.25); } 78% { opacity: 0.9; transform: scale(1); } }\n#st-mochi-celebration .stage:hover #sprout {\n      animation: sproutPerk--mochi-celebration 0.8s ease-in-out infinite;\n    }\n@keyframes sproutPerk--mochi-celebration {\n      0%, 100% { transform: rotate(0deg) scale(1); }\n      30% { transform: rotate(6deg) scale(1.08); }\n      70% { transform: rotate(-5deg) scale(1.04); }\n    }\n</style>\n<div class=\"mochi-state\" id=\"st-mochi-celebration\" data-loop=\"2.8\">\n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1254 1254\" width=\"100%\" height=\"100%\">\n      <defs>\n        <!-- Sprout linear gradient -->\n        <linearGradient id=\"sproutGrad--mochi-celebration\" x1=\"790\" y1=\"380\" x2=\"950\" y2=\"265\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#E76437\"/>\n          <stop offset=\"55%\" stop-color=\"#F89236\"/>\n          <stop offset=\"100%\" stop-color=\"#FA9F3C\"/>\n        </linearGradient>\n\n        <!-- Body soft 3D gradient (centered front-facing, seamless round bottom) -->\n        <linearGradient id=\"bodyGrad--mochi-celebration\" x1=\"627\" y1=\"330\" x2=\"627\" y2=\"990\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#F8EFE5\"/>\n          <stop offset=\"68%\" stop-color=\"#F6ECE1\"/>\n          <stop offset=\"78%\" stop-color=\"#ECE0D2\"/>\n          <stop offset=\"88%\" stop-color=\"#DECFC0\"/>\n          <stop offset=\"96%\" stop-color=\"#C7B3A1\"/>\n          <stop offset=\"100%\" stop-color=\"#BCA594\"/>\n        </linearGradient>\n\n        <!-- Visor faceplate gradient -->\n        <linearGradient id=\"visorGrad--mochi-celebration\" x1=\"627\" y1=\"420\" x2=\"627\" y2=\"812\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#2B283B\"/>\n          <stop offset=\"100%\" stop-color=\"#211F2D\"/>\n        </linearGradient>\n\n        <!-- Paws Gradient -->\n        <linearGradient id=\"handGrad--mochi-celebration\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n          <stop offset=\"0%\" stop-color=\"#FFFDFB\"/>\n          <stop offset=\"50%\" stop-color=\"#FAF1E7\"/>\n          <stop offset=\"100%\" stop-color=\"#D5C1AF\"/>\n        </linearGradient>\n\n        <!-- Terminal Glow Filter -->\n        <filter id=\"terminalGlow--mochi-celebration\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n          <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n          <feMerge>\n            <feMergeNode in=\"blur\"/>\n            <feMergeNode in=\"SourceGraphic\"/>\n          </feMerge>\n        </filter>\n      </defs>\n\n      <!-- Background Layer -->\n      \n\n      <!-- Living Character: Mochi -->\n      <g id=\"mochi\">\n        <!-- Sprout (behind head) -->\n        <path id=\"sprout\" d=\"M 780 375 C 820 410, 835 365, 890 350 C 945 350, 972 310, 960 286 C 958 264, 940 260, 910 255 C 872 255, 832 275, 806 310 C 770 348, 772 370, 780 375 Z\" fill=\"url(#sproutGrad--mochi-celebration)\"/>\n\n        <!-- Main Body (Smooth rounded mochi silhouette, no feet) -->\n        <path id=\"body\" d=\"M 627 335 C 730 335, 835 375, 905 440 C 960 495, 974 570, 974 645 C 974 770, 930 870, 835 940 C 775 985, 700 985, 627 985 C 554 985, 479 985, 419 940 C 324 870, 280 770, 280 645 C 280 570, 294 495, 349 440 C 419 375, 524 335, 627 335 Z\" fill=\"url(#bodyGrad--mochi-celebration)\"/>\n\n        <!-- Dark Visor Faceplate -->\n        <path id=\"visor\" d=\"M 627 420 C 725 420, 815 440, 858 480 C 892 515, 897 565, 897 615 C 897 670, 890 720, 855 758 C 812 795, 725 812, 627 812 C 529 812, 442 795, 399 758 C 364 720, 357 670, 357 615 C 357 565, 362 515, 396 480 C 439 440, 529 420, 627 420 Z\" fill=\"url(#visorGrad--mochi-celebration)\"/>\n\n        <!-- Face Group -->\n        <g id=\"face-group\">\n          <!-- Eyes -->\n          <g id=\"eyes\" fill=\"#FAF1E7\">\n            <path id=\"left-eye\" class=\"eye\" d=\"M 457 655 C 446 655, 439 646, 439 634 C 439 598, 468 572, 505 572 C 542 572, 571 598, 571 634 C 571 646, 564 655, 553 655 C 543 655, 537 646, 536 635 C 533 618, 521 608, 505 608 C 489 608, 477 618, 474 635 C 473 646, 467 655, 457 655 Z\"/>\n            <path id=\"right-eye\" class=\"eye\" d=\"M 797 655 C 808 655, 815 646, 815 634 C 815 598, 786 572, 749 572 C 712 572, 683 598, 683 634 C 683 646, 690 655, 701 655 C 711 655, 717 646, 718 635 C 721 618, 733 608, 749 608 C 765 608, 777 618, 780 635 C 781 646, 787 655, 797 655 Z\"/>\n          </g>\n\n          <!-- Cheeks / Blush -->\n          <g id=\"blush\" fill=\"#FA9B6A\">\n            <ellipse id=\"blush-left-1\" cx=\"442\" cy=\"695\" rx=\"24\" ry=\"12\" transform=\"rotate(35 442 695)\"/>\n            <ellipse id=\"blush-left-2\" cx=\"482\" cy=\"705\" rx=\"22\" ry=\"12\" transform=\"rotate(22 482 705)\"/>\n            <ellipse id=\"blush-right-1\" cx=\"812\" cy=\"695\" rx=\"24\" ry=\"12\" transform=\"rotate(-35 812 695)\"/>\n            <ellipse id=\"blush-right-2\" cx=\"772\" cy=\"705\" rx=\"22\" ry=\"12\" transform=\"rotate(-22 772 705)\"/>\n          </g>\n        </g>\n        \n      </g>\n    </svg>\n</div>",
