    html: "<style>\n#st-mochi-getting-sleepy .stage {\n      position: relative;\n      width: min(80vmin, 640px);\n      height: min(80vmin, 640px);\n      display: flex;\n      align-items: center;\n      justify-content: center;\n    }\n#st-mochi-getting-sleepy svg {\n      width: 100%;\n      height: 100%;\n      display: block;\n      overflow: visible;\n    }\n#st-mochi-getting-sleepy #body { transform-origin: 627px 985px; animation: sleepyDroop--mochi-getting-sleepy 6.4s cubic-bezier(0.4, 0.0, 0.2, 1) infinite;; }\n@keyframes sleepyDroop--mochi-getting-sleepy { 0%, 100% { transform: scale(1, 1) translateY(0px) rotate(0deg); } 24% { transform: scale(1.01, 0.99) translateY(2px); } 48% { transform: scale(1.025, 0.97) translateY(8px) rotate(1deg); } 62% { transform: scale(1.035, 0.96) translateY(12px) rotate(2.5deg); } 70% {  transform: scale(0.97, 1.035) translateY(-5px) rotate(-0.5deg); } 82% { transform: scale(1.008, 0.992) translateY(1px); } 92% { transform: scale(1, 1) translateY(0px); } }\n#st-mochi-getting-sleepy #sprout { transform-origin: 810px 375px; animation: sleepySproutDroop--mochi-getting-sleepy 6.4s ease-in-out infinite;; }\n@keyframes sleepySproutDroop--mochi-getting-sleepy { 0%, 100% { transform: rotate(0deg); } 48% { transform: rotate(3deg); } 62% { transform: rotate(5deg) scale(0.96); } 70% { transform: rotate(-4deg) scale(1.08); } 82% { transform: rotate(1deg); } }\n#st-mochi-getting-sleepy #visor { transform-origin: 627px 615px; animation: sleepyVisor--mochi-getting-sleepy 6.4s ease-in-out infinite;; }\n@keyframes sleepyVisor--mochi-getting-sleepy { 0%, 100% { transform: translateY(0px) rotate(0deg); } 48% { transform: translateY(6px) rotate(1deg); } 62% { transform: translateY(10px) rotate(2deg); } 70% { transform: translateY(-4px) rotate(0deg); } }\n#st-mochi-getting-sleepy .eye { transform-box: fill-box; transform-origin: center center; animation: heavyEyelids--mochi-getting-sleepy 6.4s infinite;; }\n@keyframes heavyEyelids--mochi-getting-sleepy { 0%, 20% { transform: scaleY(1); } 38% { transform: scaleY(0.5) translateY(3px); } 58%, 66% { transform: scaleY(0.12) translateY(6px); } 70%, 88% { transform: scaleY(1); } 90% { transform: scaleY(0.65); } 92%, 100% { transform: scaleY(1); } }\n#st-mochi-getting-sleepy #blush { animation: sleepyBlush--mochi-getting-sleepy 6.4s ease-in-out infinite;; }\n@keyframes sleepyBlush--mochi-getting-sleepy { 0%, 100% { opacity: 0.9; } 50%, 65% { opacity: 0.75; } 72% { opacity: 1; } }\n#st-mochi-getting-sleepy .stage:hover #sprout {\n      animation: sproutPerk--mochi-getting-sleepy 0.8s ease-in-out infinite;\n    }\n@keyframes sproutPerk--mochi-getting-sleepy {\n      0%, 100% { transform: rotate(0deg) scale(1); }\n      30% { transform: rotate(6deg) scale(1.08); }\n      70% { transform: rotate(-5deg) scale(1.04); }\n    }\n</style>\n<div class=\"mochi-state\" id=\"st-mochi-getting-sleepy\" data-loop=\"6.4\">\n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 1254 1254\" width=\"100%\" height=\"100%\">\n      <defs>\n        <!-- Sprout linear gradient -->\n        <linearGradient id=\"sproutGrad--mochi-getting-sleepy\" x1=\"790\" y1=\"380\" x2=\"950\" y2=\"265\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#E76437\"/>\n          <stop offset=\"55%\" stop-color=\"#F89236\"/>\n          <stop offset=\"100%\" stop-color=\"#FA9F3C\"/>\n        </linearGradient>\n\n        <!-- Body soft 3D gradient (centered front-facing, seamless round bottom) -->\n        <linearGradient id=\"bodyGrad--mochi-getting-sleepy\" x1=\"627\" y1=\"330\" x2=\"627\" y2=\"990\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#F8EFE5\"/>\n          <stop offset=\"68%\" stop-color=\"#F6ECE1\"/>\n          <stop offset=\"78%\" stop-color=\"#ECE0D2\"/>\n          <stop offset=\"88%\" stop-color=\"#DECFC0\"/>\n          <stop offset=\"96%\" stop-color=\"#C7B3A1\"/>\n          <stop offset=\"100%\" stop-color=\"#BCA594\"/>\n        </linearGradient>\n\n        <!-- Visor faceplate gradient -->\n        <linearGradient id=\"visorGrad--mochi-getting-sleepy\" x1=\"627\" y1=\"420\" x2=\"627\" y2=\"812\" gradientUnits=\"userSpaceOnUse\">\n          <stop offset=\"0%\" stop-color=\"#2B283B\"/>\n          <stop offset=\"100%\" stop-color=\"#211F2D\"/>\n        </linearGradient>\n\n        <!-- Paws Gradient -->\n        <linearGradient id=\"handGrad--mochi-getting-sleepy\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n          <stop offset=\"0%\" stop-color=\"#FFFDFB\"/>\n          <stop offset=\"50%\" stop-color=\"#FAF1E7\"/>\n          <stop offset=\"100%\" stop-color=\"#D5C1AF\"/>\n        </linearGradient>\n\n        <!-- Terminal Glow Filter -->\n        <filter id=\"terminalGlow--mochi-getting-sleepy\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n          <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n          <feMerge>\n            <feMergeNode in=\"blur\"/>\n            <feMergeNode in=\"SourceGraphic\"/>\n          </feMerge>\n        </filter>\n      </defs>\n\n      <!-- Background Layer -->\n      \n\n      <!-- Living Character: Mochi -->\n      <g id=\"mochi\">\n        <!-- Sprout (behind head) -->\n        <path id=\"sprout\" d=\"M 780 375 C 820 410, 835 365, 890 350 C 945 350, 972 310, 960 286 C 958 264, 940 260, 910 255 C 872 255, 832 275, 806 310 C 770 348, 772 370, 780 375 Z\" fill=\"url(#sproutGrad--mochi-getting-sleepy)\"/>\n\n        <!-- Main Body (Smooth rounded mochi silhouette, no feet) -->\n        <path id=\"body\" d=\"M 627 335 C 730 335, 835 375, 905 440 C 960 495, 974 570, 974 645 C 974 770, 930 870, 835 940 C 775 985, 700 985, 627 985 C 554 985, 479 985, 419 940 C 324 870, 280 770, 280 645 C 280 570, 294 495, 349 440 C 419 375, 524 335, 627 335 Z\" fill=\"url(#bodyGrad--mochi-getting-sleepy)\"/>\n\n        <!-- Dark Visor Faceplate -->\n        <path id=\"visor\" d=\"M 627 420 C 725 420, 815 440, 858 480 C 892 515, 897 565, 897 615 C 897 670, 890 720, 855 758 C 812 795, 725 812, 627 812 C 529 812, 442 795, 399 758 C 364 720, 357 670, 357 615 C 357 565, 362 515, 396 480 C 439 440, 529 420, 627 420 Z\" fill=\"url(#visorGrad--mochi-getting-sleepy)\"/>\n\n        <!-- Face Group -->\n        <g id=\"face-group\">\n          <!-- Eyes -->\n          <g id=\"eyes\" fill=\"#FAF1E7\">\n            <path id=\"left-eye\" class=\"eye\" d=\"M 444 638 C 444 650, 470 686, 505 686 C 540 686, 566 650, 566 638 C 566 626, 554 624, 544 634 C 534 646, 520 654, 505 654 C 490 654, 476 646, 466 634 C 456 624, 444 626, 444 638 Z\"/>\n            <path id=\"right-eye\" class=\"eye\" d=\"M 810 638 C 810 650, 784 686, 749 686 C 714 686, 688 650, 688 638 C 688 626, 700 624, 710 634 C 720 646, 734 654, 749 654 C 764 654, 778 646, 788 634 C 798 624, 810 626, 810 638 Z\"/>\n          </g>\n\n          <!-- Cheeks / Blush -->\n          <g id=\"blush\" fill=\"#FA9B6A\">\n            <ellipse id=\"blush-left-1\" cx=\"442\" cy=\"695\" rx=\"24\" ry=\"12\" transform=\"rotate(35 442 695)\"/>\n            <ellipse id=\"blush-left-2\" cx=\"482\" cy=\"705\" rx=\"22\" ry=\"12\" transform=\"rotate(22 482 705)\"/>\n            <ellipse id=\"blush-right-1\" cx=\"812\" cy=\"695\" rx=\"24\" ry=\"12\" transform=\"rotate(-35 812 695)\"/>\n            <ellipse id=\"blush-right-2\" cx=\"772\" cy=\"705\" rx=\"22\" ry=\"12\" transform=\"rotate(-22 772 705)\"/>\n          </g>\n        </g>\n        \n      </g>\n    </svg>\n</div>",
